def analytical_gradients(x, y, w, b):
    pred = linear_model(x, w, b)

    error = pred - y

    grad_w = (
        2.0 * error * x
    ).mean().reshape_as(w)

    grad_b = (
        2.0 * error
    ).mean().reshape_as(b)

    return grad_w, grad_b

def numerical_gradients(
    x, y, w, b, eps=1e-3
):
    w_plus = w.clone()
    w_minus = w.clone()

    w_plus[0, 0] += eps
    w_minus[0, 0] -= eps

    loss_plus = mse_loss(
        linear_model(x, w_plus, b),
        y
    )

    loss_minus = mse_loss(
        linear_model(x, w_minus, b),
        y
    )

    return (
        loss_plus - loss_minus
    ) / (2 * eps)

